// Transparent space connected to the image boundary, excluding internal holes.
function outerSpace(labels,width,height,transparent){const mask=new Uint8Array(labels.length),queue=new Int32Array(labels.length);let head=0,tail=0;function push(i){if(!mask[i]&&labels[i]===transparent){mask[i]=1;queue[tail++]=i;}}for(let x=0;x<width;x++){push(x);push((height-1)*width+x);}for(let y=0;y<height;y++){push(y*width);push(y*width+width-1);}while(head<tail){const i=queue[head++],x=i%width;if(x)push(i-1);if(x<width-1)push(i+1);if(i>=width)push(i-width);if(i<labels.length-width)push(i+width);}return mask;}
function traceWithOuterSmoothing(image,options,labels,transparent,strength='balanced'){
 const settings={gentle:{passes:1,radius:2,window:3,shift:.4,fit:2},balanced:{passes:4,radius:5,window:7,shift:2,fit:.25},strong:{passes:6,radius:8,window:10,shift:3.5,fit:.1}}[strength]||{passes:4,radius:5,window:7,shift:2,fit:.25};
 const {width,height}=image,exterior=outerSpace(labels,width,height,transparent);const stats={strength,exteriorTransparentPixels:exterior.reduce((a,b)=>a+b,0),outerPoints:0,movedPoints:0,maxShiftPx:0};let layerIndex=0;
 function outside(p){const x=Math.floor(p.x),y=Math.floor(p.y);for(let yy=y-1;yy<=y;yy++)for(let xx=x-1;xx<=x;xx++)if(xx<0||yy<0||xx>=width||yy>=height||exterior[yy*width+xx])return true;return false;}
 const originalInternodes=ImageTracer.internodes,originalFit=ImageTracer.fitseq;
 ImageTracer.internodes=function(paths,opts){const visible=layerIndex++!==transparent;const result=originalInternodes(paths,opts);for(const path of result){const points=path.points,n=points.length;const source=points.map(p=>({...p}));const boundary=source.map(outside);if(visible)stats.outerPoints+=boundary.filter(Boolean).length;for(let i=0;i<n;i++)points[i].coasterprintOuter=n>=12&&boundary[i];if(n<12)continue;
 const movable=source.map((b,i)=>{for(let k=-settings.window;k<=settings.window;k++)if(!boundary[(i+k+n)%n])return false;const a=source[(i-settings.window+n)%n],c=source[(i+settings.window)%n],ux=b.x-a.x,uy=b.y-a.y,vx=c.x-b.x,vy=c.y-b.y;return (ux*vx+uy*vy)/(Math.hypot(ux,uy)*Math.hypot(vx,vy)||1)>=.72;});
 for(let pass=0;pass<settings.passes;pass++){const prev=points.map(p=>({x:p.x,y:p.y}));for(let i=0;i<n;i++){if(!movable[i])continue;let x=0,y=0,sum=0;for(let k=-settings.radius;k<=settings.radius;k++){const weight=Math.exp(-k*k/(settings.radius*settings.radius*.7));const p=prev[(i+k+n)%n];x+=p.x*weight;y+=p.y*weight;sum+=weight;}x/=sum;y/=sum;const dx=x-source[i].x,dy=y-source[i].y,length=Math.hypot(dx,dy),f=length>settings.shift?settings.shift/length:1;points[i].x=source[i].x+dx*f;points[i].y=source[i].y+dy*f;}}
 if(visible)for(let i=0;i<n;i++){const shift=Math.hypot(points[i].x-source[i].x,points[i].y-source[i].y);if(shift>.01){stats.movedPoints++;stats.maxShiftPx=Math.max(stats.maxShiftPx,shift);}}
 // Preserve original direction flags for every untouched interior segment.
 for(let i=0;i<n;i++){const next=(i+1)%n;if(points[i].x!==source[i].x||points[i].y!==source[i].y||points[next].x!==source[next].x||points[next].y!==source[next].y)points[i].linesegment=ImageTracer.getdirection(points[i].x,points[i].y,points[next].x,points[next].y);}}
 return result;};
 ImageTracer.fitseq=function(path,ltres,qtres,start,end){let all=true,i=start;do{if(!path.points[i].coasterprintOuter){all=false;break;}i=(i+1)%path.points.length;}while(i!==end&&i!==start);if(!path.points[end].coasterprintOuter)all=false;return originalFit(path,all?settings.fit:ltres,all?settings.fit:qtres,start,end);};
 try{const result=ImageTracer.imagedataToTracedata(image,options);result.coasterprintSmoothing=stats;return result;}finally{ImageTracer.internodes=originalInternodes;ImageTracer.fitseq=originalFit;}
}
